public class InversionCounterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("countInversions({2,4,1,3,5})", 3L,
                    InversionCounter.countInversions(new int[] {2, 4, 1, 3, 5}));
            check("countInversions({}) is 0", 0L,
                    InversionCounter.countInversions(new int[] {}));
            check("countInversions({5,4,3,2,1})", 10L,
                    InversionCounter.countInversions(new int[] {5, 4, 3, 2, 1}));
            check("countInversions({2,2,2}) ties are not inversions", 0L,
                    InversionCounter.countInversions(new int[] {2, 2, 2}));

            int[] descending = new int[1000];
            for (int i = 0; i < descending.length; i++) {
                descending[i] = descending.length - i;
            }
            check("countInversions(1000 descending)", 499500L,
                    InversionCounter.countInversions(descending));

            check("firstOutOfOrderIndex({1,2,3})", -1,
                    InversionCounter.firstOutOfOrderIndex(new int[] {1, 2, 3}));
            check("firstOutOfOrderIndex({1,5,4,9})", 1,
                    InversionCounter.firstOutOfOrderIndex(new int[] {1, 5, 4, 9}));
            check("firstOutOfOrderIndex({}) is -1", -1,
                    InversionCounter.firstOutOfOrderIndex(new int[] {}));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected exception: " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

